<template><view><view class="page-heading"><text class="kicker">JUST THE TWO OF US</text><text class="title">{{ space.name }}</text><text class="copy">每一处都可以保留你们自己的称呼和样子。</text></view>
  <view class="people-grid"><view v-for="member in members" :key="member.id" class="person v2-card"><Avatar :src="member.avatar_url" :name="member.display_name" :frame="member.avatar_frame" :size="66"/><text>{{ member.display_name }}</text><text>{{ member.user && member.user.id === user.id ? '这是你' : '空间成员' }}</text></view><button v-if="members.length<2" class="person invite v2-card" @click="$emit('invite')"><view class="plus">+</view><text>邀请另一半</text><text>复制专属邀请码</text></button></view>
  <view class="settings v2-card"><button @click="$emit('customize')"><view><text>装扮我们的空间</text><text>主题、背景、头像、菜单与名称</text></view><text class="arrow">›</text></button><button @click="$emit('invite')"><view><text>邀请与成员</text><text>生成新的邀请码</text></view><text class="arrow">›</text></button><button class="logout" @click="$emit('logout')"><view><text>退出登录</text><text>不会删除空间内容</text></view><text class="arrow">›</text></button></view>
</view></template>
<script setup>import Avatar from './Avatar.vue';defineProps({space:Object,members:{type:Array,default:()=>[]},user:{type:Object,default:()=>({})}});defineEmits(['invite','customize','logout'])</script>
<style scoped>.page-heading{text-align:center;padding:12px 0 25px}.kicker{display:block;color:var(--color-primary);font-size:9px;letter-spacing:2px;font-weight:800}.title{display:block;font-family:Georgia,'Songti SC',serif;font-size:29px;font-weight:700;margin-top:8px}.copy{display:block;color:var(--color-muted);font-size:12px;margin-top:8px}.people-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.person{min-height:150px;padding:20px 10px;display:flex;flex-direction:column;align-items:center;justify-content:center;background:var(--color-surface)}.person>text:nth-last-child(2){font-size:15px;font-weight:700;margin-top:10px}.person>text:last-child{font-size:10px;color:var(--color-muted);margin-top:4px}.person.invite{border:1px dashed var(--color-secondary);color:var(--color-text)}.person.invite::after{border:0}.plus{width:46px;height:46px;line-height:43px;border:1px solid var(--color-secondary);border-radius:50%;font-size:25px;color:var(--color-secondary)}.settings{margin-top:17px;padding:0 17px;background:var(--color-surface)}.settings button{height:69px;background:transparent;padding:0;display:flex;align-items:center;justify-content:space-between;text-align:left;border-bottom:1px solid rgba(47,41,37,.07);border-radius:0}.settings button:last-child{border:0}.settings button::after{border:0}.settings button view text{display:block}.settings button view text:first-child{font-size:14px;font-weight:700;color:var(--color-text)}.settings button view text:last-child{font-size:10px;color:var(--color-muted);margin-top:4px}.arrow{color:var(--color-muted);font-size:24px;font-family:serif}.settings .logout view text:first-child{color:var(--color-primary)}@media(min-width:720px){.people-grid{max-width:620px;margin:0 auto}.settings{max-width:650px;margin:18px auto 0}}</style>
